cd /home/anupam/Desktop/workspace && source .env.langfuse 2>/dev/null && python3 - <<'EOF'
import json,os,urllib.request,base64
cred=base64.b64encode(f"{os.environ['LANGFUSE_PUBLIC_KEY']}:{os.environ['LANGFUSE_SECRET_KEY']}".encode()).decode()
def get(path):
    r=urllib.request.Request("http://localhost:3000"+path, headers={"Authorization":"Basic "+cred})
    return json.load(urllib.request.urlopen(r))
d=get("/api/public/traces?limit=200&page=1")
print("traces page1:", len(d['data']), "total:", d['meta']['totalItems'])
for t in d['data']:
    n=(t.get('name') or '')
    if 'upgrade' in n.lower() or 'v4' in n.lower() or 'langfuse' in n.lower() or 'trace' in n.lower():
        print("  cand:", n[:90], "|", t.get('id'))
EOF

