        return None
    for line in open(p, encoding="utf-8", errors="replace"):
        try:
            ev = json.loads(line)
        except Exception:
            continue
        role = str(ev.get("role") or ev.get("type") or "")
        msg = ev.get("content") or ev.get("message")
        if role.lower() in ("user", "human") and msg:
            return str(msg)[:1000]
    return None

