def post_score(self, trace_id, decision, verdict, evidence):
    """Attach a decision-holds score to the trace's root observation."""
    if not self.auth or not trace_id:
        return None
    try:
        t = self.get_json(f"/api/public/traces/{trace_id}")
        oid = (t.get("observationIds") or [None])[0]
        body = {"batch": [{
            "id": str(uuid.uuid4()),
            "type": "score-create",
            "timestamp": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
            "body": {
                "name": "factory:decision-holds",
                "value": 1.0 if verdict == "PASS" else 0.0,
                "traceId": trace_id,
                "observationId": oid,
                "comment": evidence[:500],
                "metadata": {"decision": decision, "verdict": verdict},
            },
        }]}
        r = urllib.request.Request(
            self.base + "/api/public/ingestion", data=json.dumps(body).encode(),
            headers={"Authorization": self.auth, "Content-Type": "application/json"})
        with urllib.request.urlopen(r, timeout=15) as resp:
            return resp.status == 201 or resp.status == 200
    except Exception:
        return None

